// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount, address caller) public {
        vm.assume(recipient != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        vm.prank(caller);
        bool ok = true;
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }
        bool expectedOk = (caller == c.owner());
        assertTrue(ok == expectedOk);
    }
}
